// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role, address account) public {
        vm.assume(account != address(0) && account != address(this));
        vm.prank(account);
        try c.renounceRole(role, account) {} catch {}
        bool hasAfterRenounce = c.hasRole(role, account);
        assertTrue(!hasAfterRenounce);
    }
}
